def choose_move(observation):
    def clamp(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def to_tuple(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def get_pos(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            for k in ("pos", "position", "loc", "location", "xy", "coord", "coordinates", "agent_pos"):
                if k in obj:
                    p = to_tuple(obj.get(k))
                    if p is not None:
                        return p
            x = obj.get("x", None)
            y = obj.get("y", None)
            if x is not None and y is not None:
                return x, y
        return to_tuple(obj)

    def find_first_pos(value):
        if value is None:
            return None
        p = get_pos(value)
        if p is not None:
            return p
        if isinstance(value, dict):
            for v in value.values():
                p = find_first_pos(v)
                if p is not None:
                    return p
        elif isinstance(value, (list, tuple)):
            for v in value:
                p = find_first_pos(v)
                if p is not None:
                    return p
        return None

    def positions_from(value):
        out = []
        if value is None:
            return out
        if isinstance(value, dict):
            p = get_pos(value)
            if p is not None:
                out.append(p)
            for v in value.values():
                out.extend(positions_from(v))
        elif isinstance(value, (list, tuple)):
            p = get_pos(value)
            if p is not None:
                out.append(p)
            else:
                for v in value:
                    out.extend(positions_from(v))
        return out

    def get_grid():
        for k in ("grid", "map", "board", "terrain", "cells", "world"):
            g = observation.get(k, None)
            if g is not None:
                return g
        return None

    def get_self_pos():
        for k in ("self", "agent", "player", "me"):
            v = observation.get(k, None)
            p = find_first_pos(v)
            if p is not None:
                return p
        for k in ("agent_pos", "player_pos", "my_pos", "position", "pos", "loc", "location"):
            p = get_pos(observation.get(k, None))
            if p is not None:
                return p
        return None

    me = get_self_pos()
    if me is None:
        me = (0, 0)
    mx, my = me[0], me[1]

    grid = get_grid()
    width = observation.get("width", None)
    height = observation.get("height", None)
    if isinstance(grid, (list, tuple)) and grid:
        if width is None:
            try:
                width = len(grid[0])
            except Exception:
                width = None
        if height is None:
            try:
                height = len(grid)
            except Exception:
                height = None

    threats = []
    targets = []
    friends = []

    for key in ("enemies", "enemy", "opponents", "opponent", "hazards", "threats", "predators", "chasers"):
        threats.extend(positions_from(observation.get(key, None)))

    for key in ("resources", "resource", "goals", "goal", "targets", "target", "food", "items", "collectibles", "capture_points", "bases", "territory"):
        targets.extend(positions_from(observation.get(key, None)))

    for key in ("allies", "ally", "friends", "teammates", "team"):
        friends.extend(positions_from(observation.get(key, None)))

    # Fallback: scan nested observation for any obvious positions if nothing found.
    if not threats:
        for k, v in observation.items():
            if k not in ("grid", "map", "board", "terrain", "cells", "world"):
                if isinstance(v, (dict, list, tuple)):
                    pv = positions_from(v)
                    if len(pv) and len(pv) <= 32:
                        lower = str(k).lower()
                        if "enemy" in lower or "opp" in lower or "hazard" in lower or "threat" in lower:
                            threats.extend(pv)

    if not targets:
        for k, v in observation.items():
            if isinstance(v, (dict, list, tuple)):
                pv = positions_from(v)
                if len(pv) and len(pv) <= 32:
                    lower = str(k).lower()
                    if "resource" in lower or "goal" in lower or "target" in lower or "food" in lower or "point" in lower or "territ" in lower:
                        targets.extend(pv)

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    # If grid provides blocked cells, infer impassable.
    blocked = set()
    if isinstance(grid, (list, tuple)):
        for y, row in enumerate(grid):
            if isinstance(row, (list, tuple)):
                for x, cell in enumerate(row):
                    if cell in (1, True, "X", "x", "#", "W", "wall", "blocked", "obstacle"):
                        blocked.add((x, y))

    def in_bounds(x, y):
        if width is not None and (x < 0 or x >= width):
            return False
        if height is not None and (y < 0 or y >= height):
            return False
        return True

    def dist2(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def score_move(dx, dy):
        nx, ny = mx + dx, my + dy
        if (nx, ny) in blocked:
            return -10**9
        if not in_bounds(nx, ny):
            return -10**9

        s = 0.0

        # Prefer staying if surrounded by threats; otherwise allow motion.
        if dx == 0 and dy == 0:
            s += 0.5

        if targets:
            d0 = min(dist2((mx, my), t) for t in targets)
            d1 = min(dist2((nx, ny), t) for t in targets)
            s += (d0 - d1) * 4.0

        if threats:
            d0 = min(dist2((mx, my), e) for e in threats)
            d1 = min(dist2((nx, ny), e) for e in threats)
            s += (d1 - d0) * 6.0
            if d1 == 0:
                s -= 100.0

        # Territory/control heuristic: move toward center if no clear target.
        if not targets:
            if width is not None and height is not None:
                cx, cy = width / 2.0, height / 2.0
                s += (abs(mx - cx) - abs(nx - cx)) * 0.25
                s += (abs(my - cy) - abs(ny - cy)) * 0.25

        # Avoid clustering with allies if lots of them nearby.
        if friends:
            f0 = min(dist2((mx, my), f) for f in friends)
            f1 = min(dist2((nx, ny), f) for f in friends)
            s += (f1 - f0) * 0.2

        # Mild inertia to reduce jitter: keep moving same way if still sensible.
        if dx == 0 and dy == 0:
            s -= 0.1
        else:
            s += 0.05

        return s

    best = (0, 0)
    best_score = -10**18
    for dx, dy in moves:
        sc = score_move(dx, dy)
        if sc > best_score:
            best_score = sc
            best = (dx, dy)

    return [clamp(best[0]), clamp(best[1])]

